export const baseFilter = (): Record<string, any> => ({
    transType: "PAY",
    "info.desc": AUGMENT_PROVISIONAL_REVENUE,
    serviceCode: COLLECTION_DISBURSEMENT
});

/** UC02.R03 filters, mirroring buildFilter of GET /ops/collection-disbursement/collections */
export const buildFilter = (params: any): Record<string, any> => {
    const filter: Record<string, any> = baseFilter();
    const and: Record<string, any>[] = [];

    if (!isEmptyValue(params.transId)) { filter.transId = String(params.transId).trim(); }
    if (!isEmptyValue(params.status)) { filter.status = { $in: String(params.status).split(",") }; }
    if (!isEmptyValue(params.serviceCode)) { and.push({ serviceCode: params.serviceCode }); }
    if (!isEmptyValue(params.merchantEmail)) { filter["info.masterMerchantInfo.email"] = like(params.merchantEmail); }
    if (!isEmptyValue(params.payeeCode)) { filter["info.merchantInfo.code"] = like(params.payeeCode); }
    if (params.payeeType === PAYEE_TYPE.USER) {
        // Collection is only for merchants for now, a wallet user beneficiary never matches
        filter["info.merchantInfo.code"] = { $exists: false };
    }
    if (params.dateFr || params.dateTo) {
        filter.createdAt = {};
        if (params.dateFr) { filter.createdAt.$gte = new Date(params.dateFr); }
        if (params.dateTo) { filter.createdAt.$lte = new Date(params.dateTo); }
    }
    if (!isEmptyValue(params.billId)) {
        const asNumber = Number(params.billId);
        and.push({ "info.billId": { $in: Number.isNaN(asNumber) ? [String(params.billId)] : [asNumber, String(asNumber)] } });
    }
    if (and.length > 0) { filter.$and = and; }
    return filter;

