export const validateParams = <T>(ClassDTO: any, params: any, langCode: string = "vi"): T => {
    const lang = (langCode === "en" || langCode === "vi") ? langCode : "vi";
    const input = params || {};
    const objectData = plainToInstance(ClassDTO, input);
    const errors = validateSync(objectData as object);

    if (errors.length > 0) {
        const errorToHandle = errors[0];
        const constraints = errorToHandle.constraints || {};
        let rawConstraintCode: string;

        if (constraints.hasOwnProperty("isNotEmpty")) {
            rawConstraintCode = constraints.isNotEmpty;
        } else {
            const constraintKey = Object.keys(constraints)[0];
            rawConstraintCode = constraints[constraintKey] || constraintKey;
        }

        const translatedConstraint = VALIDATION_MESSAGES[rawConstraintCode]?.[lang] || rawConstraintCode;
        const prefix = DEFAULT_VALIDATION_PREFIX[lang];

        throw new Errors.ValidationError(`${prefix}: ${translatedConstraint}`);
    }

    return objectData as T;

